            if isinstance(row, (list, tuple)) and j < len(row):
                return row[j]
        return None

    # Heuristic signals: proximity to resource 'R', enemy 'E', territory 'T'
    best_dx, best_dy = 0, 0
    best_score = -10

    # Priority: move toward resource, avoid danger, but also secure territory if present
    for dx in (-1, 0, 1):
