            if score > best_score:
                best_score = score
                best_dx, best_dy = dx, dy

    # If nothing better found (best_score <= 0), pick a safe random-like move deterministically:
    if best_score <= 0:
        # Simple deterministic fallback: move toward center of grid if possible, else stay
        cx = (width - 1) // 2
        cy = (height - 1) // 2
        fx = 1 if cx > x else -1 if cx < x else 0
        fy = 1 if cy > y else -1 if cy < y else 0
